"""Chapter 3: Acids and Bases (20 new multiple choice + 50 free response; 30 multiple choice already exist)."""
from qb import *

OH = '[H:4][O-:1].[H:2][Cl:3]'           # hydroxide and HCl drawn together so arrows can join them
ARR2 = (('bondf', 2, 3, .2), ('atom', 3), {'bend': .7, 'e_off': -9})
ARR_OK = [(('lp', 1), ('atom', 2), {'bend': .35}), ARR2]


def build(b):
    # ------------------------------------------------------------ 3.1 Introduction
    b.mc('3.1', 1, 'In the reaction HCl + H₂O ⇌ Cl⁻ + H₃O⁺, which species is the conjugate base of HCl?', 'Cl⁻', ['H₃O⁺', 'H₂O', 'HO⁻'], 'The conjugate base is what remains after the acid loses a proton.')
    b.mc('3.1', 2, 'In which reaction does water act as an acid?', 'CH₃CH₂O⁻ + H₂O ⇌ CH₃CH₂OH + HO⁻', ['HBr + H₂O → Br⁻ + H₃O⁺', 'CH₃CO₂H + H₂O ⇌ CH₃CO₂⁻ + H₃O⁺', 'H₂SO₄ + H₂O → HSO₄⁻ + H₃O⁺'],
         'Only in the first reaction does water donate a proton (becoming HO⁻); in the others it accepts one.')
    b.fr('3.1', 1, 'Define a Brønsted-Lowry acid and a Brønsted-Lowry base.', 'An acid is a proton (H⁺) donor and a base is a proton acceptor.', 'The definition is based on the transfer of a proton.')
    b.fr('3.1', 1, 'In NH₃ + HCl → NH₄⁺ + Cl⁻, identify the acid, base, conjugate acid and conjugate base.', 'Acid: HCl; base: NH₃; conjugate acid: NH₄⁺; conjugate base: Cl⁻.', 'HCl donates the proton to NH₃.')
    b.fr('3.1', 2, 'Water can act as an acid or as a base. Write one reaction for each and name the conjugate partner formed.', 'As a base: HCl + H₂O → Cl⁻ + H₃O⁺ (conjugate acid H₃O⁺). As an acid: CH₃O⁻ + H₂O → CH₃OH + HO⁻ (conjugate base HO⁻).', 'Water is amphoteric.')
    b.fr('3.1', 2, 'Give the conjugate acid of CH₃NH₂ and the conjugate base of CH₃OH.', 'The conjugate acid of CH₃NH₂ is CH₃NH₃⁺; the conjugate base of CH₃OH is CH₃O⁻.', 'Add a proton to the base; remove a proton from the acid.')
    # ------------------------------------------------------------ 3.2 Curved arrows
    b.mc('3.2', 2, 'What is the minimum number of curved arrows needed to show a proton transfer?', 'Two', ['One', 'Three', 'Four'], 'One arrow shows the base attacking the proton and a second shows the X-H bond breaking.')
    b.mc('3.2', 3, 'Which curved arrows correctly show hydroxide removing a proton from HCl?', A(OH, ARR_OK, lone=[3]),
         [A(OH, ARR_OK[:1], lone=[3]), A(OH, [(('atom', 2), ('lp', 1), {'bend': .35}), (('atom', 3), ('bondf', 2, 3, .2), {'bend': .7})], lone=[3]), A(OH, [(('lp', 1), ('atom', 3), {'bend': .35}), (('bondf', 2, 3, .2), ('atom', 2), {'bend': .7})], lone=[3])],
         'Arrow 1 starts on a lone pair of the base and ends on the proton; arrow 2 starts on the H-Cl bond and ends on chlorine.', oimg=True)
    b.fr('3.2', 2, 'Draw the curved arrows for the reaction of hydroxide with HCl.', 'Arrow 1: from a lone pair on HO⁻ to the hydrogen of HCl. Arrow 2: from the H-Cl bond to the chlorine atom, giving H₂O and Cl⁻.', 'Tail on the electron source, head on where the electrons go.', aimg=A(OH, ARR_OK, lone=[3]))
    b.fr('3.2', 2, 'Why does every proton transfer need at least two curved arrows?', 'One arrow shows the base forming a bond to the proton and a second shows the bond to the proton breaking, so the proton is never left with two bonds.', 'A hydrogen cannot hold more than one bond.')
    b.fr('3.2', 3, 'Describe the curved arrows for CH₃CO₂H reacting with hydroxide, including where each arrow starts and ends.', 'Arrow 1: from a lone pair on HO⁻ to the acidic hydrogen. Arrow 2: from the O-H bond of the acid to its oxygen atom, forming CH₃CO₂⁻ and H₂O.', 'The base attacks the proton and the O-H bond electrons move onto oxygen.', img=S('CC(=O)O', '@+', '[OH-]'))
    b.fr('3.2', 3, 'For NH₃ + HBr, state where the tail and head of each curved arrow are placed.', 'Arrow 1 starts on the nitrogen lone pair and ends on the H of HBr. Arrow 2 starts on the H-Br bond and ends on bromine, forming NH₄⁺ and Br⁻.', 'Lone pair attacks the proton; the H-Br bond leaves with its electrons.')
    # ------------------------------------------------------------ 3.3 pKa
    b.mc('3.3', 1, 'Which acid is stronger: one with pKa 4.75 or one with pKa 15.7?', 'The one with pKa 4.75', ['The one with pKa 15.7', 'They are equally strong', 'It depends on the solvent only'], 'A lower pKa means a stronger acid.')
    b.mc('3.3', 2, 'Acid A has pKa 5 and acid B has pKa 9. How many times more acidic is A than B?', '10,000 times', ['4 times', '40 times', '1,000 times'], 'Each pKa unit is a factor of ten, so four units is 10⁴.')
    b.mc('3.3', 2, 'For CH₃CO₂H + HO⁻ ⇌ CH₃CO₂⁻ + H₂O (pKa of CH₃CO₂H = 4.75; pKa of H₂O = 15.7), which side is favored?', 'The products', ['The reactants', 'Neither side', 'It cannot be predicted'], 'Equilibrium favors the weaker acid, water (higher pKa).')
    b.fr('3.3', 1, 'Which is more acidic, ethanol (pKa 16) or acetic acid (pKa 4.75)? By about how many orders of magnitude?', 'Acetic acid is more acidic, by about 11 orders of magnitude.', '16 - 4.75 is roughly 11 pKa units.')
    b.fr('3.3', 2, 'Use pKa values to rank from weakest to strongest acid: NH₃ (38), HC≡CH (25), H₂O (15.7).', 'NH₃ < HC≡CH < H₂O.', 'The higher the pKa, the weaker the acid.')
    b.fr('3.3', 2, 'Predict the position of the equilibrium HC≡CH + NH₂⁻ ⇌ HC≡C⁻ + NH₃ (pKa of HC≡CH = 25; pKa of NH₃ = 38).', 'The products are favored, because NH₃ (pKa 38) is the weaker acid.', 'Equilibrium favors the weaker acid.')
    b.fr('3.3', 2, 'Rank HO⁻, CH₃CO₂⁻ and NH₂⁻ from weakest to strongest base. (Conjugate acid pKa values: H₂O 15.7, CH₃CO₂H 4.75, NH₃ 38.)', 'CH₃CO₂⁻ < HO⁻ < NH₂⁻.', 'The weaker the conjugate acid, the stronger the base.')
    b.fr('3.3', 3, 'The pKa of H₃O⁺ is -1.74 and that of NH₄⁺ is 9.3. Which is the stronger base, H₂O or NH₃? Explain.', 'NH₃ is the stronger base, because its conjugate acid (NH₄⁺) is the weaker acid.', 'A weak acid has a strong conjugate base.')
    b.fr('3.3', 3, 'HA has pKa 15 and HB has pKa 5. Which side is favored in A⁻ + HB ⇌ HA + B⁻? Explain.', 'The products. HB is the stronger acid, so the equilibrium favors the weaker acid (HA) and the weaker base (B⁻).', 'The stronger acid reacts with the stronger base.')
    # ------------------------------------------------------------ 3.4 Factors affecting anion stability (ARIO)
    b.mc('3.4.1', 2, 'Which is the stronger acid, HF or HCl?', 'HCl, because Cl⁻ is larger and spreads the charge over more space', ['HF, because F is more electronegative', 'They are equally acidic', 'HF, because F⁻ is smaller'], 'Within a column, size beats electronegativity.')
    b.mc('3.4.3', 2, 'Which compound is the stronger acid?', 'CF₃CH₂OH, because the fluorines stabilize the alkoxide by induction', ['CH₃CH₂OH, because it has fewer halogens', 'They are equally acidic', 'CH₃CH₂OH, because its oxygen is more electronegative'], 'The electron-withdrawing CF₃ group stabilizes the negative charge of the conjugate base.', img=S('CCO', 'OCC(F)(F)F', labels='I II'))
    b.mc('3.4.4', 2, 'Which hydrogen is the most acidic?', 'The H on the sp carbon (the alkyne C-H)', ['The H on the sp² carbon', 'A H on the CH₃ group', 'They are equally acidic'], 'An sp orbital holds the negative charge closer to the nucleus.', img=S('CC#C'))
    b.fr('3.4.1', 1, 'Which is more acidic, H₂O or H₂S? Explain.', 'H₂S, because S is larger than O, so HS⁻ spreads its charge over a larger volume.', 'Compare atoms in the same column by size.')
    b.fr('3.4.1', 2, 'Which is more acidic, NH₃ or H₂O? Explain.', 'H₂O, because oxygen is more electronegative than nitrogen and stabilizes the negative charge of HO⁻ better.', 'Same row: electronegativity decides.')
    b.fr('3.4.1', 2, 'Which is more acidic, CH₃OH or CH₃SH? Explain.', 'CH₃SH, because CH₃S⁻ is larger than CH₃O⁻ and stabilizes charge better (size dominates within a column).', 'O and S are in the same column.')
    b.fr('3.4.2', 2, 'Which is more acidic, ethanol or acetic acid? Explain using the conjugate bases.', 'Acetic acid; the acetate ion is stabilized by resonance (charge on two oxygens), but ethoxide has a localized charge.', 'Both charges are on oxygen, so compare resonance.', img=S('CCO', 'CC(=O)O', labels='I II'))
    b.fr('3.4.2', 2, 'Which N-H is more acidic, the amide N-H or the amine N-H? Explain.', 'The amide N-H; its conjugate base has the charge delocalized onto the carbonyl oxygen by resonance.', 'Both charges are on nitrogen, so compare resonance.', img=S('CNCCC(=O)NC'))
    b.fr('3.4.2', 3, 'Phenol is a stronger acid than cyclohexanol. Explain using the conjugate bases.', 'Phenoxide is stabilized by resonance (the negative charge delocalizes onto ortho and para carbons), but cyclohexoxide has a localized charge.', 'Both anions have the charge on oxygen.', img=S('Oc1ccccc1', 'OC1CCCCC1', labels='I II'))
    b.fr('3.4.3', 2, 'Which is the stronger acid, CH₃CO₂H or ClCH₂CO₂H? Explain.', 'ClCH₂CO₂H; the electronegative chlorine withdraws electron density through the σ bonds (induction) and stabilizes the carboxylate.', 'Same atom and resonance; induction differs.', img=S('CC(=O)O', 'OC(=O)CCl', labels='I II'))
    b.fr('3.4.3', 2, 'Which is the stronger acid: 2-chlorobutanoic acid or 4-chlorobutanoic acid? Explain.', '2-Chlorobutanoic acid, because the chlorine is closer to the carboxylate and the inductive effect weakens with distance.', 'Induction decreases as the number of bonds between Cl and the acid group increases.', img=S('CCC(Cl)C(=O)O', 'ClCCCC(=O)O', labels='I II'))
    b.fr('3.4.3', 3, 'Which O-H is more acidic in this compound? Explain.', 'The O-H on the carbon bearing the two CF₃ groups; the six fluorines stabilize that alkoxide by induction.', 'Compare the inductive effect near each alkoxide.', img=S('OC(C(F)(F)F)(C(F)(F)F)CCCO'))
    b.fr('3.4.4', 1, 'Which is more acidic, ethane or ethyne? Explain.', 'Ethyne; its conjugate base has the charge in an sp orbital, which is closer to the nucleus and more stable.', 'sp > sp² > sp³ for stabilizing a negative charge.', img=S('CC', 'C#C', labels='I II'))
    b.fr('3.4.4', 2, 'In 1-butene-3-yne only one hydrogen is much more acidic than the others. Which hydrogen is it and why?', 'The alkyne hydrogen on the sp carbon; the conjugate base has its charge in an sp orbital.', 'Compare sp, sp² and sp³ carbon-hydrogen bonds.', img=S('C=CC#C'))
    b.fr('3.4.4', 3, 'Explain why an sp orbital stabilizes a negative charge better than an sp³ orbital.', 'An sp orbital has 50% s character, and s electrons are held closer to the nucleus than p electrons, so the lone pair is lower in energy.', 'More s character means the electrons are closer to the positive nucleus.')
    b.fr('3.4.5', 3, 'Which is more acidic, the O-H of propan-1-ol or the C-H of propyne (on the sp carbon)? Name the factor that decides.', 'The O-H, because the atom (O versus C) takes priority over the orbital effect.', 'Order of priority: atom, resonance, induction, orbital.', img=S('CCCO', 'CC#C', labels='I II'))
    b.fr('3.4.5', 3, 'Which O-H is more acidic in this compound? Explain which factor wins.', 'The carboxylic acid O-H; resonance (a delocalized carboxylate) is more important than the inductive effect of the nearby CCl₃ group.', 'Atom ties; resonance outranks induction.', img=S('OC(=O)CCC(O)C(Cl)(Cl)Cl'))
    b.fr('3.4.5', 3, 'Which C-H is more acidic: the CH₂ between two carbonyls in CH₃COCH₂COCH₃, or the terminal alkyne C-H in HC≡CH? Explain.', 'The CH₂ between the carbonyls; its conjugate base is resonance stabilized (charge on two oxygens), which outranks the orbital effect.', 'Both are carbon acids; resonance outranks orbitals.', img=S('CC(=O)CC(C)=O', 'C#C', labels='I II'))
    b.fr('3.4.5', 4, 'Rank from least to most acidic and explain: I = HC≡CH, II = CH₃CH₂OH, III = CH₃COCH₂COCH₃ (central CH₂).', 'I < II < III. Acetylene is a carbon acid (an sp carbanion); ethanol puts the charge on oxygen (atom beats orbital); the diketone anion is resonance stabilized (charge on two oxygens), which outranks atom alone.',
         'Compare the conjugate bases using atom, resonance, induction and orbital in order.', img=S('C#C', 'CCO', 'CC(=O)CC(C)=O', labels='I II III'))
    # ------------------------------------------------------------ 3.5 Cationic acids
    b.mc('3.5', 2, 'Which is the stronger acid, NH₄⁺ or H₃O⁺?', 'H₃O⁺, because oxygen is less able than nitrogen to stabilize a positive charge', ['NH₄⁺, because nitrogen is less electronegative', 'They are equally strong', 'NH₄⁺, because it has more hydrogens'], 'A positive charge is more stable on the less electronegative atom.')
    b.mc('3.5', 2, 'Which is the stronger base, CH₃NH₂ or CH₃OH?', 'CH₃NH₂', ['CH₃OH', 'They are equally basic', 'Neither is basic'], 'Nitrogen holds a positive charge better than oxygen, so the amine is more easily protonated.')
    b.mc('3.5', 3, 'Aniline is a weaker base than methylamine because:', 'The nitrogen lone pair of aniline is delocalized into the ring', ['Nitrogen in aniline is less electronegative', 'Aniline has no lone pair', 'The ring is electron donating by induction only'], 'A delocalized lone pair is less available to accept a proton.', img=S('Nc1ccccc1', 'CN', labels='I II'))
    b.fr('3.5', 2, 'Draw the conjugate acid of CH₃CH₂NH₂. Which atom carries the positive charge?', 'CH₃CH₂NH₃⁺; the nitrogen carries the positive charge.', 'Protonate the nitrogen lone pair.', aimg=S('CC[NH3+]'))
    b.fr('3.5', 2, 'Why are amines stronger bases than alcohols?', 'Nitrogen is less electronegative than oxygen, so a positive charge on nitrogen (the conjugate acid) is more stable than on oxygen.', 'Compare the stability of the conjugate acids.')
    b.fr('3.5', 3, 'Explain why amides are extremely poor bases.', 'The nitrogen lone pair is delocalized onto the carbonyl oxygen by resonance, so it is not available to accept a proton.', 'A delocalized lone pair is a weak base.', img=S('CC(=O)N'))
    b.fr('3.5', 3, 'Which is the stronger acid, CH₃NH₃⁺ (pKa 10.6) or C₆H₅NH₃⁺ (pKa 4.6)? Explain using the conjugate bases.', 'C₆H₅NH₃⁺; its conjugate base (aniline) has a lone pair delocalized into the ring, making it the weaker base.', 'Strong acid means weak conjugate base.')
    b.fr('3.5', 2, 'Draw the product of protonating pyridine and state which atom is protonated.', 'The nitrogen is protonated, giving the pyridinium ion.', 'The nitrogen lone pair lies in the plane of the ring, not in the π system.', img=S('C1=CC=NC=C1'), aimg=S('C1=CC=[NH+]C=C1'))
    # ------------------------------------------------------------ 3.6 Position of equilibrium and choice of reagents
    b.mc('3.6', 2, 'Which side is favored in NH₂⁻ + CH₃OH ⇌ NH₃ + CH₃O⁻?', 'The products', ['The reactants', 'Neither side', 'Cannot be predicted'], 'Equilibrium favors the more stable anion: O⁻ is more stable than N⁻ (same row).')
    b.mc('3.6', 3, 'Is water a suitable proton source to convert the acetate ion into acetic acid?', 'No; the equilibrium favors acetate because it is a resonance-stabilized, weaker base than HO⁻', ['Yes; water is a strong acid', 'Yes; the equilibrium favors acetic acid', 'No, because water has no protons'], 'H₂O + CH₃CO₂⁻ → CH₃CO₂H + HO⁻ is uphill; a stronger acid such as H₃O⁺ is needed.')
    b.fr('3.6', 2, 'Predict the position of equilibrium: CH₃CO₂⁻ + HCl ⇌ CH₃CO₂H + Cl⁻.', 'The products are favored, because Cl⁻ is a much weaker base than acetate.', 'HCl is the stronger acid.')
    b.fr('3.6', 2, 'Is hydroxide a strong enough base to deprotonate phenol? Explain.', 'Yes. Phenoxide is resonance stabilized, so phenol (pKa 9.9) is a stronger acid than water (15.7) and the equilibrium favors phenoxide.', 'The equilibrium favors the more stable anion.')
    b.fr('3.6', 3, 'A student wants to convert CH₃CH₂OH completely into its alkoxide. Is NaOH or NaNH₂ the better choice? Explain.', 'NaNH₂. Ethanol (pKa 16) and water (15.7) have similar acidity, so NaOH gives only a partial equilibrium, whereas NH₂⁻ is a far stronger base (NH₃ pKa 38) and deprotonates ethanol completely.', 'Compare the conjugate acids of the two bases.')
    b.fr('3.6', 3, 'Is water a suitable proton source to protonate CH₃CH₂O⁻? Explain.', 'Yes. Water (pKa 15.7) is about as acidic as ethanol (16), so the equilibrium lies roughly in balance and favors the alcohol with excess water.', 'Compare the acidities of water and ethanol.')
    b.fr('3.6', 3, 'Is hydroxide a suitable base to deprotonate acetylene? Explain.', 'No. Acetylene (pKa 25) is far less acidic than water (15.7), so the equilibrium favors the reactants. A base such as NH₂⁻ is needed.', 'Equilibrium favors the weaker acid.')
    # ------------------------------------------------------------ 3.7 Leveling effect
    b.mc('3.7', 2, 'What is the strongest base that can exist in water?', 'HO⁻', ['NH₂⁻', 'CH₃CH₂⁻', 'H⁻'], 'Any base stronger than HO⁻ reacts with water to give HO⁻ (the leveling effect).')
    b.mc('3.7', 2, 'What happens when sodium amide (NaNH₂) is added to water?', 'It reacts with water to give NH₃ and HO⁻', ['It dissolves unchanged as NH₂⁻', 'It forms NH₄⁺', 'Nothing; amide is not basic'], 'NH₂⁻ is a stronger base than HO⁻, so it is destroyed by the solvent.')
    b.fr('3.7', 2, 'State the leveling effect for bases in a solvent.', 'The strongest base that can exist in a solvent is the conjugate base of the solvent; any stronger base reacts with the solvent.', 'In water the limit is HO⁻.')
    b.fr('3.7', 3, 'Why can NaNH₂ not be used as a base in water, and what solvent could be used instead?', 'NH₂⁻ deprotonates water, giving HO⁻. Liquid ammonia (or a solvent such as THF) can be used because it is not deprotonated.', 'Choose a solvent whose conjugate base is at least as strong as the base.')
    b.fr('3.7', 2, 'What is the strongest acid that can exist in water?', 'H₃O⁺; a stronger acid such as HCl simply protonates water to form H₃O⁺.', 'The leveling effect applies to acids as well.')
    # ------------------------------------------------------------ 3.8 Solvating effects
    b.mc('3.8', 2, 'Why is the tert-butoxide ion less stable than the ethoxide ion in solution?', 'It is bulky, so solvent molecules cannot approach and stabilize the negative oxygen as well', ['It has a smaller negative charge', 'It has resonance structures', 'It has fewer carbon atoms'], 'Steric hindrance reduces solvation.', img=S('CC(C)(C)[O-]', 'CC[O-]', labels='I II'))
    b.fr('3.8', 2, 'Ethanol (pKa 16) is slightly more acidic than tert-butanol (pKa 18). Explain.', 'Ethoxide is better solvated than the sterically hindered tert-butoxide, so it is more stable and ethanol is the stronger acid.', 'Solvation depends on how well solvent molecules reach the charge.')
    b.fr('3.8', 3, 'Predict which is the stronger base, CH₃O⁻ or (CH₃)₃CO⁻, and explain how solvation contributes.', '(CH₃)₃CO⁻ is stronger, because the bulky groups hinder solvation of its negative charge, leaving it less stabilized.', 'Less stabilized means a stronger base.')
    # ------------------------------------------------------------ 3.9 Counterions
    b.mc('3.9', 1, 'In the reagent NaOH, which ion acts as the base?', 'HO⁻', ['Na⁺', 'Both ions equally', 'Neither ion'], 'The sodium counterion is a spectator.')
    b.fr('3.9', 1, 'What is a counterion?', 'A positively charged species (such as Na⁺, K⁺, Li⁺) that accompanies a negatively charged base; it usually does not take part in the reaction.', 'It is also called a spectator ion.')
    b.fr('3.9', 2, 'Rewrite NaNH₂ + H₂O → NH₃ + NaOH without the counterion.', 'NH₂⁻ + H₂O → NH₃ + HO⁻', 'Na⁺ is a spectator.')
    # ------------------------------------------------------------ 3.10 Lewis acids and bases
    b.mc('3.10', 2, 'Which species is a Lewis acid?', 'BF₃', ['NH₃', 'H₂O', 'CH₃O⁻'], 'BF₃ has an empty p orbital and accepts an electron pair.', img=S('B(F)(F)F'))
    b.fr('3.10', 2, 'In BF₃ + O(CH₃)₂ → F₃B⁻-O⁺(CH₃)₂, identify the Lewis acid and the Lewis base.', 'BF₃ is the Lewis acid (electron-pair acceptor); dimethyl ether is the Lewis base (electron-pair donor).', 'The oxygen lone pair is donated to boron.')
    b.fr('3.10', 2, 'BF₃ has no hydrogens. Explain how it can still be an acid.', 'It is a Lewis acid: boron has an empty p orbital and accepts an electron pair.', 'Lewis acidity is defined by electron-pair acceptance, not proton donation.')
    b.fr('3.10', 3, 'How many curved arrows are needed for NH₃ + BF₃ → H₃N⁺-B⁻F₃? Draw it.', 'One: from the nitrogen lone pair to boron.', 'A Lewis acid-base reaction forms one new bond, so one arrow is enough.', aimg=A('[NH3:1].[B:2](F)(F)F', [(('lp', 1), ('atom', 2), {'bend': .3})], lone=[1]))
